package build

import (
	"fmt"
	"go/format"
	"strings"
)

// generateApplication owns only Qi assembly; Gordis generates module files.
func generateApplication(m Manifest) (map[string][]byte, error) {
	// Only explicitly selected factories are imported into the generated
	// application. Their registration metadata is composed without starting a Host.
	var plugins strings.Builder
	fmt.Fprintf(
		&plugins,
		"// Code generated by qi-build; DO NOT EDIT.\npackage compiledplugins\n\nimport (\nbuiltin %q\n%q\n",
		BuiltinModule+"/bundle",
		CoreModule+"/boot/application",
	)

	for i, p := range m.Plugins {
		fmt.Fprintf(&plugins, "selected%d %q\n", i, p.Package)
	}

	plugins.WriteString(")\n\nfunc Application() (application.Application, error) {\nreturn application.Compose(\nbuiltin.Extension(),\n")

	for i := range m.Plugins {
		fmt.Fprintf(&plugins, "selected%d.Extension(),\n", i)
	}

	plugins.WriteString(")\n}\n")
	main := fmt.Sprintf(`// Code generated by qi-build; DO NOT EDIT.
package main

import (
    "fmt"
    "os"
    boot %q
    %q
    %q
)

func main() {
    application, err := compiledplugins.Application()
    if err != nil {
        fmt.Fprintln(os.Stderr, "compiled extensions:", err)
        os.Exit(1)
    }
    os.Exit(boot.Run(os.Args[1:], launch.Input{Stdin: os.Stdin, Stdout: os.Stdout, Stderr: os.Stderr}, application))
}
`, CoreModule+"/boot", CoreModule+"/boot/launch", generatedModule+"/internal/compiledplugins")
	files := map[string][]byte{
		"main.go": []byte(main),
		"internal/compiledplugins/plugins_gen.go": []byte(plugins.String()),
	}

	for name, raw := range files {
		if strings.HasSuffix(name, ".go") {
			formatted, err := format.Source(raw)
			if err != nil {
				return nil, err
			}

			files[name] = formatted
		}
	}

	return files, nil
}
